<?php
declare(strict_types=1);
final class ExportService{
 public function __construct(private PDO$db){$this->audit=new AuditService($db);}private AuditService$audit;
 public function generate(string$type,string$format='csv'):int{$allowed=['perfumes'=>['SELECT name,slug,gender,concentration,availability_status,status,short_description FROM perfumes WHERE deleted_at IS NULL','name,slug,gender,concentration,availability_status,status,short_description'],'brands'=>['SELECT name,slug,country,is_active FROM brands WHERE deleted_at IS NULL','name,slug,country,is_active'],'categories'=>['SELECT name,slug,parent_id,is_active FROM categories WHERE deleted_at IS NULL','name,slug,parent_id,is_active'],'families'=>['SELECT name,slug,is_active FROM olfactory_families WHERE deleted_at IS NULL','name,slug,is_active'],'notes'=>['SELECT name,slug,note_group,is_active FROM notes WHERE deleted_at IS NULL','name,slug,note_group,is_active'],'tags'=>['SELECT name,slug,is_active FROM tags WHERE deleted_at IS NULL','name,slug,is_active']];if(!isset($allowed[$type]))throw new InvalidArgumentException('Tipo de exportación no permitido.');$dir=dirname(__DIR__,2).'/storage/exports';if(!is_dir($dir))mkdir($dir,0750,true);$name='export_'.$type.'_'.date('Ymd_His').'_'.bin2hex(random_bytes(5)).'.'.$format;$path=$dir.'/'.$name;$s=$this->db->query($allowed[$type][0]);$rows=$s->fetchAll(PDO::FETCH_NUM);$headers=explode(',',$allowed[$type][1]);$count=$format==='json'?(new JsonExportService())->write($path,array_merge([$headers],$rows)):(new CsvExportService())->write($path,$headers,$rows);$ins=$this->db->prepare('INSERT INTO exports(type,format,filename,file_path,file_size,file_hash,row_count,expires_at,completed_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$ins->execute([$type,$format,$name,$path,filesize($path),hash_file('sha256',$path),$count,date('Y-m-d H:i:s',time()+Env::int('EXPORT_RETENTION_HOURS',24)*3600)]);$id=(int)$this->db->lastInsertId();$this->audit->record('export_created','export',$id,['type'=>$type,'rows'=>$count]);return$id;}
}
